function trialEnd(start,months=3){const date=new Date(start);if(!Number.isFinite(date.getTime()))throw new Error('תאריך ניסיון לא תקין');const day=date.getUTCDate();date.setUTCDate(1);date.setUTCMonth(date.getUTCMonth()+months);const days=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth()+1,0)).getUTCDate();date.setUTCDate(Math.min(day,days));return date.toISOString()}
function planState(subscription,teacher,now=Date.now()){if(teacher)return{kind:'teacher',text:'מסלול מורה — חינם, ללא הגבלת תקופת ניסיון.'};if(!subscription)return{kind:'none',text:'תקופת הניסיון המשפחתית תתחיל עם קישור ההורה לילד הראשון.'};if(subscription.status==='active'&&subscription.current_period_end&&new Date(subscription.current_period_end).getTime()>now)return{kind:'active',text:'המנוי המשפחתי פעיל עד '+new Date(subscription.current_period_end).toLocaleDateString('he-IL')};if(new Date(subscription.trial_ends_at).getTime()>now&&subscription.status==='trialing'){const days=Math.ceil((new Date(subscription.trial_ends_at)-now)/86400000);return{kind:'trial',text:`ניסיון משפחתי חינם — נותרו ${days} ימים, עד ${new Date(subscription.trial_ends_at).toLocaleDateString('he-IL')}.`}}return{kind:'expired',text:'תקופת הניסיון הסתיימה. המשך בתשלום יתאפשר לאחר חיבור שירות התשלומים.'}}
function demoSubscription(){try{return JSON.parse(localStorage.getItem('homework-demo-trial:'+activeStudentId()))}catch{return null}}
function renderPricing(){const config=window.NOHOMEWORK_PLAN;const amount=config.monthlyAgorot;document.getElementById('familyPrice').textContent=amount===null?'מחיר חודשי — ייקבע':(amount/100).toLocaleString('he-IL',{minimumFractionDigits:2,maximumFractionDigits:2})+' ₪ לחודש';document.getElementById('priceConfirmation').textContent=amount===null?'מחיר מוצע: '+(config.proposedMonthlyAgorot/100)+' ₪ לחודש למשפחה. טרם נקבע מחיר סופי.':'לאחר 3 חודשי ניסיון חינם.';const subscription=cloud.ready?cloud.subscriptions.find(s=>s.owner_parent_id===cloud.user.id)||cloud.subscriptions[0]:demoSubscription();document.getElementById('subscriptionStatus').textContent=planState(subscription,role==='teacher').text;document.getElementById('demoStartTrial').hidden=cloud.enabled||role!=='parent'||!!subscription;document.getElementById('subscriptionAction').hidden=role==='teacher';}
document.getElementById('demoStartTrial').onclick=()=>{if(cloud.enabled||role!=='parent'||!activeStudentId())return;const now=new Date().toISOString();try{localStorage.setItem('homework-demo-trial:'+activeStudentId(),JSON.stringify({status:'trialing',trial_started_at:now,trial_ends_at:trialEnd(now)}));document.getElementById('billingMessage').textContent='זו הדמיית ניסיון בלבד. לא נפתח מנוי ולא יבוצע חיוב.';renderPricing()}catch{document.getElementById('billingMessage').textContent='לא ניתן לשמור את הניסיון בדפדפן הזה.'}};
document.getElementById('subscriptionAction').onclick=()=>{document.getElementById('billingMessage').textContent=role==='child'?'המנוי מנוהל על ידי ההורה. אין חיוב מתוך חשבון תלמיד.':'שירות התשלומים טרם מחובר. לא נאספים פרטי כרטיס ולא מתבצע חיוב.'};renderPricing();
